typedef struct {
    uint32_t codepoint;
    uint16_t width;
    uint16_t height;
    int16_t x_offset;
    int16_t y_offset;
    int16_t advance;
    const uint8_t *bitmap;
} bitmap_glyph_t;

typedef struct {
    const bitmap_glyph_t *glyphs;
    size_t count;
} bitmap_font_t;

